import { describe, expect, it } from 'vitest';
import { readdirSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { brandSvgs, RASTERS } from '../../scripts/brand/marks.mjs';

// The brand files under static/ are generated by scripts/brand/build.mjs from marks.mjs. These tests
// fail when a committed file drifts from its source, when a file is added by hand, or when an icon
// the browser is told about does not exist at the size it is announced at.
const staticDir = fileURLToPath(new URL('../../static/', import.meta.url));
const read = (path: string) => readFileSync(staticDir + path);

// Read independently of the generator, so a wrong size in build.mjs cannot vouch for itself.
function pngSize(buf: Buffer): string {
	expect(buf.subarray(12, 16).toString('latin1')).toBe('IHDR');
	return `${buf.readUInt32BE(16)}x${buf.readUInt32BE(20)}`;
}
function icoSizes(buf: Buffer): number[] {
	expect(buf.readUInt16LE(2)).toBe(1);
	return Array.from({ length: buf.readUInt16LE(4) }, (_, i) => buf.readUInt8(6 + 16 * i) || 256);
}

describe('brand assets', () => {
	const svgs = brandSvgs();

	it('commits every generated vector byte for byte', () => {
		const drifted = Object.entries(svgs).filter(([path, text]) => read(path).toString() !== text);
		expect(Object.keys(svgs).length).toBe(20);
		expect(drifted.map(([path]) => path)).toEqual([]);
	});

	it('holds nothing in static/brand that the generator does not produce', () => {
		const expected = [...Object.keys(svgs), ...Object.keys(RASTERS)]
			.filter((p) => p.startsWith('brand/'))
			.map((p) => p.slice('brand/'.length))
			.sort();
		expect(readdirSync(staticDir + 'brand').sort()).toEqual(expected);
	});

	it('writes each raster at its declared pixel size', () => {
		for (const [path, r] of Object.entries(RASTERS)) {
			const buf = read(path);
			if ('sizes' in r) expect(icoSizes(buf), path).toEqual(r.sizes);
			else expect(pngSize(buf), path).toBe(`${r.width}x${r.height}`);
		}
	});

	it('announces in the manifest only generated icons, at their real size', () => {
		const manifest = JSON.parse(read('manifest.webmanifest').toString());
		expect(manifest.icons.length).toBe(3);
		for (const icon of manifest.icons) {
			const path = icon.src.replace(/^\//, '');
			expect(Object.keys(RASTERS), icon.src).toContain(path);
			expect(pngSize(read(path)), icon.src).toBe(icon.sizes);
		}
	});

	it('links from app.html only to files that exist', () => {
		const html = readFileSync(fileURLToPath(new URL('../app.html', import.meta.url)), 'utf8');
		const hrefs = [...html.matchAll(/href="%sveltekit\.assets%\/([^"]+)"/g)].map((m) => m[1]);
		expect(hrefs).toEqual([
			'favicon.ico',
			'brand/icon.svg',
			'apple-touch-icon.png',
			'manifest.webmanifest'
		]);
		for (const href of hrefs) expect(() => read(href), href).not.toThrow();
	});
});
